ST.xhtml:
// gen_sin_(PT:=T#1S, AM:=50, OS:= 0, DL:=0);
// Буфер для хранения данных датчика момента
ibuff();
// Обрабатываем данные датчика момента
GVL.rTorque := GetCompensatedTorque(GVL.iTorque_RAW, GVL.iTorque_ADC_offset); // Вычисляем значение датчика момента с учетом начального смещения
GVL.rTorqueCalibrated := GetCalibratedTorque(GVL.rTorque);			// Вычисляем скорректированное значение датчика момента
GVL.iTorqueScaled := CalculateScaledTorque(GVL.rTorqueCalibrated);	// Масштабированное значение для записи в буфер обмена
ibuff.InVal := GVL.iTorqueScaled;									// Добавляем очередное значение в буфер

// ---------- Запись и обработка данных регистров ModbusTCP -------------------
//=============================================================================
// ПЛК -> ПО АРМ
//=============================================================================
MB_DI		 := GVL.DI.WDI;					// Дискретные входы
//-----------------------------------------------------------------------------
MB_TN 		 := TO_WORD(GVL.iTorque_RAW); 	// Данные с АЦП тензодатчика
//-----------------------------------------------------------------------------
MB_EN	 	 := _dint_to_word2(GVL.udiEncoder_RAW); // Энкодер угла
//-----------------------------------------------------------------------------
MB_DQ	 	 := GVL.DQ.WDQ;					// Состояние дискретных выходов
//-----------------------------------------------------------------------------
_T._S_STATE := GVL.State;
MB_STATE    := _T._WORD;		// Статус системы управления
//-----------------------------------------------------------------------------
MB_TN_OFFSET := TO_WORD(GVL.iTorque_ADC_offset); // Смещение 0 АЦП тензодатчика
//-----------------------------------------------------------------------------
MB_EN_OFFSET := _dint_to_word2(GVL.udiEncoderOffset); // Смещение 0 энкодера угла
//-----------------------------------------------------------------------------
MB_BUF_TN 	 := ibuff.Out_WORDS; // Копируем текущие данные буфера датчика в буфер MODBUS
//-----------------------------------------------------------------------------
MB_HEAD 	 := ibuff.head;	 	 // Счетчик позициии указателя на начало текущего буфера

//=============================================================================
// Запись ПО АРМ -> ПЛК
//=============================================================================
IF GVL.fbAlarm.xAlarm THEN
	_T._WORD := MB_CTRL AND 16#FFFE;		// Общая авария, аварийный останов		
ELSE
	_T._WORD := MB_CTRL;		 
END_IF
GVL.Control		:= _T._S_CTRL;	 // Команда управления
//-----------------------------------------------------------------------------
GVL.iTorqueSV	:= TO_INT(MB_TORQUE_SV);		// Задание момента в Нм * 500
//-----------------------------------------------------------------------------
GVL.iJogVelocity := TO_INT(MB_VELOCITY_SV);		// Скорость привода в JOG режиме
												// в град/сек * 1000
//-----------------------------------------------------------------------------
_T._WORD 		:= MB_DQ_CTRL;	 // Прямое управление выходами ПЛК с ПО АРМ
GVL.DQ_Control	:= _T._PDQ;		 // (только в сервисном режиме)
//-----------------------------------------------------------------------------
GVL.UZ_Control 	:=  MB_UZ_CTRL;	// Прямое управление UZ (только в сервисном режиме)

//-----------------------------------------------------------------------------
xWriteRetain(CLK:= GVL.Control.WriteRetain);

IF xWriteRetain.Q THEN
	// Коэффициенты ПИД регулятора
	GVL.KP := _word_to_real(MB_KP);
	GVL.KI := _word_to_real(MB_KI);
	GVL.KD := _word_to_real(MB_KD);
	// Коэффициенты аппроксимации датчика момента
	GVL.rA1 := _word_to_real(MB_A1);
	GVL.rB1 := _word_to_real(MB_B1);
	GVL.rC1 := _word_to_real(MB_C1);
	GVL.rA2 := _word_to_real(MB_A2);
	GVL.rB2 := _word_to_real(MB_B2);
	// Диапазон датчика момента
	GVL.iTorqueSensorRange := 50; //TO_UINT(MB_TQ_RANGE);
END_IF
